export function buildTrustSecurityView({ permissions = [], secrets = [], events = [] } = {}) { return Object.freeze({ permissions: Object.freeze(permissions.map((item) => Object.freeze({ label: String(item.label), capabilityId: String(item.capabilityId), state: item.state ?? 'deny' }))), secrets: Object.freeze(secrets.map((item) => Object.freeze({ provider: String(item.provider), configured: Boolean(item.value || item.configured), lastUsedAt: item.lastUsedAt ?? null, rotationStatus: item.rotationStatus ?? 'unknown' }))), events: Object.freeze(events.map((item) => Object.freeze({ ...item }))) }); }
export function renderTrustSecurityView(value) { return `<section><h1>Trust & Security</h1><p>${value.permissions.length} permissions · ${value.secrets.length} secret connections</p></section>`; }
